import{_ as e,o,c as a,a3 as i}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"HTML blocks","description":"Embed custom HTML on a page — with and without form fields.","frontmatter":{"title":"HTML blocks","description":"Embed custom HTML on a page — with and without form fields."},"headers":[],"relativePath":"en/seiten/html-bloecke.md","filePath":"en/seiten/html-bloecke.md","lastUpdated":1787319236000}'),r={name:"en/seiten/html-bloecke.md"};function s(l,t,n,d,h,c){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="html-blocks" tabindex="-1">HTML blocks <a class="header-anchor" href="#html-blocks" aria-label="Permalink to &quot;HTML blocks&quot;">​</a></h1><p>Two blocks let you use custom HTML code when the built-in blocks aren&#39;t enough.</p><table tabindex="0"><thead><tr><th>Block</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>HTML</strong></td><td><em>Embed custom HTML or generate it with AI</em></td></tr><tr><td><strong>HTML with form fields</strong></td><td><em>Embed custom HTML and add form fields with AI</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Check first whether you can do without</p><p>HTML blocks are powerful, but more work to maintain than the built-in blocks: they don&#39;t follow along with redesigns, and colleagues without HTML knowledge can&#39;t change them.</p><p>First check whether <a href="/en/seiten/layout-bloecke">layout blocks</a> with background color and border radius are enough.</p></div><hr><h2 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h2><h3 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h3><p><strong>Edit HTML</strong> opens the code editor with <strong>HTML code</strong> and <strong>Live preview</strong> side by side.</p><table tabindex="0"><thead><tr><th>Function</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Generate with AI</strong></td><td>Describe instead of write</td></tr><tr><td><strong>Restore previous HTML version</strong></td><td>Undoes the last generation</td></tr><tr><td><strong>Auto-adjust height</strong></td><td>Height follows the content</td></tr></tbody></table><p>Invalid code produces <em>Preview error</em>; a failed generation produces <em>HTML could not be generated</em>.</p><h3 id="working-with-ai" tabindex="-1">Working with AI <a class="header-anchor" href="#working-with-ai" aria-label="Permalink to &quot;Working with AI&quot;">​</a></h3><p>The input field expects a description of the desired change — for example &quot;Add a footer&quot; or &quot;Make the card responsive.&quot;</p><div class="tip custom-block"><p class="custom-block-title">Work step by step</p><p>The AI modifies the existing code. Small, clearly worded changes lead to better results than one long wish list.</p><p><em>Restore previous HTML version</em> undoes exactly one step — for important intermediate states, it&#39;s better to copy the code out separately.</p></div><h3 id="template-variables" tabindex="-1">Template variables <a class="header-anchor" href="#template-variables" aria-label="Permalink to &quot;Template variables&quot;">​</a></h3><p>The editor points out: <em>Use {{ }} for template variables. Example: {{variableName}}</em></p><p>This lets you insert values from the context into the HTML code.</p><hr><h2 id="html-with-form-fields" tabindex="-1">HTML with form fields <a class="header-anchor" href="#html-with-form-fields" aria-label="Permalink to &quot;HTML with form fields&quot;">​</a></h2><p>Like the HTML block, but the input fields it contains return data.</p><div class="danger custom-block"><p class="custom-block-title">Fields need a name or id attribute</p><p>The editor explicitly warns:</p><blockquote><p><em>Input fields without a name or id are not included in the Flow payload. Add a name or id attribute to every input field that should be submitted.</em></p></blockquote><p>Without one of these two attributes, the entered value is <strong>silently lost</strong> — there&#39;s no error message.</p></div><h3 id="verifying-the-payload" tabindex="-1">Verifying the payload <a class="header-anchor" href="#verifying-the-payload" aria-label="Permalink to &quot;Verifying the payload&quot;">​</a></h3><p><strong>Flow form payload preview</strong> and <strong>Refresh preview</strong> show which values would actually be passed.</p><div class="tip custom-block"><p class="custom-block-title">Always check before going live</p><p>This preview is the only reliable way to check whether your fields come through. If one is missing there, it&#39;s missing its <code>name</code> or <code>id</code> attribute.</p></div><hr><h2 id="limits-and-caution" tabindex="-1">Limits and caution <a class="header-anchor" href="#limits-and-caution" aria-label="Permalink to &quot;Limits and caution&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">What to keep in mind</p><ul><li><strong>No conditional display within the HTML.</strong> <a href="/en/seiten/sichtbarkeit">Conditional visibility</a> applies to the block as a whole, not to parts within it.</li><li><strong>No validation.</strong> The required-field checks from the regular input blocks don&#39;t apply here.</li><li><strong>Styling is up to you.</strong> The block doesn&#39;t automatically inherit the page&#39;s appearance.</li><li><strong>Check on narrow screens.</strong> Fixed widths break there.</li></ul></div><div class="danger custom-block"><p class="custom-block-title">No confidential data in the code</p><p>The HTML code is delivered to visitors and visible in the browser. Don&#39;t put credentials, keys, or internal addresses there.</p></div><hr><h2 id="which-block-for-what" tabindex="-1">Which block for what <a class="header-anchor" href="#which-block-for-what" aria-label="Permalink to &quot;Which block for what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Block</th></tr></thead><tbody><tr><td>Styled text, cards, spacing</td><td><a href="/en/seiten/layout-bloecke">Layout blocks</a></td></tr><tr><td>Embed external content</td><td><strong>Embed</strong> (iframe)</td></tr><tr><td>Custom look without input</td><td><strong>HTML</strong></td></tr><tr><td>Custom look with input fields</td><td><strong>HTML with form fields</strong></td></tr><tr><td>Regular data collection</td><td><a href="/en/seiten/eingabebloecke">Input blocks</a></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/bloecke">Block overview</a></li><li><a href="/en/seiten/eingabebloecke">Input blocks</a></li><li><a href="/en/seiten/sichtbarkeit">Conditional visibility</a></li></ul>',32)])])}const b=e(r,[["render",s]]);export{p as __pageData,b as default};
